                "SELECT e.race_id, e.team_id, e.roster_version, e.bib, e.entry_status, "
                        + "e.finish_time_ms, e.penalty_ms, e.total_time_ms, "
                        + "e.checkpoint_count, e.covered_checkpoint_count "
