        jdbcTemplate.batchUpdate(
                "INSERT INTO roster_lock_entry "
                        + "(race_id, team_id, roster_version, bib, entry_status, finish_time_ms, "
                        + "penalty_ms, total_time_ms, checkpoint_count, covered_checkpoint_count) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
