    /**
     * 登记退赛：插入只追加的退赛记录并把归属置为不活跃，同一成员只能退赛一次。
     *
     * @return 被置为不活跃的归属行数（0 表示重复退赛或归属缺失，调用方应先行校验）
     */
    public int insertWithdrawal(WithdrawalRow withdrawal) {
